playZap() {
    // "Auto" Skill Sound - "Fast Crescendo Bubbles"
    // Satisfying, bubbling upward sweep
    if (this.soundEnabled) {
        const ctx = this.getCtx();
        const now = ctx.currentTime;

        // 8 bubbles in rapid succession
        const bubbleCount = 8;
        const spacing = 0.035; // ~35ms between bubbles

        for (let i = 0; i < bubbleCount; i++) {
            const startTime = now + (i * spacing);
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = 'sine';

            // Rising pitch scale: Low -> High
            // Start around 300Hz, go up to ~1200Hz base
            const startFreq = 300 + (i * 120); 
            const endFreq = startFreq * 2.2; // Sharp rise for "bloop" effect

            osc.frequency.setValueAtTime(startFreq, startTime);
            osc.frequency.exponentialRampToValueAtTime(endFreq, startTime + 0.08);

            // Crescendo volume: Quiet -> Loud
            // Last bubble is the loudest
            const volume = 0.05 + (i / bubbleCount) * 0.4;

            gain.gain.setValueAtTime(0, startTime);
            gain.gain.linearRampToValueAtTime(volume, startTime + 0.01); // Instant attack
            gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.1); // Fast decay

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start(startTime);
            osc.stop(startTime + 0.15);
        }
    }

    if (this.vibrationEnabled) {
        // Trigger haptic at the peak of the crescendo for maximum satisfaction
        setTimeout(() => {
            Haptics.impact({ style: ImpactStyle.Medium });
        }, 250);
    }
}

import { Haptics, ImpactStyle } from '@capacitor/haptics';

class SoundManager {
  private ctx: AudioContext | null = null;
  private soundEnabled: boolean = true;
  private vibrationEnabled: boolean = true;
  private profile: string = 'snd-zen';

  private getCtx(): AudioContext {
    if (!this.ctx) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      this.ctx = new AudioContextClass();
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx!;
  }

  setEnabled(enabled: boolean) {
    this.soundEnabled = enabled;
  }

  setVibrationEnabled(enabled: boolean) {
    this.vibrationEnabled = enabled;
  }

  setProfile(profile: string) {
    this.profile = profile;
  }

  private async triggerHaptic(style: ImpactStyle = ImpactStyle.Light) {
    if (this.vibrationEnabled) {
      try {
        await Haptics.impact({ style });
      } catch (e) {
        // Ignore haptic errors
      }
    }
  }

  playClick() {
    if (this.soundEnabled) {
      const ctx = this.getCtx();
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.setValueAtTime(800, t);
      osc.frequency.exponentialRampToValueAtTime(1200, t + 0.05);
      gain.gain.setValueAtTime(0.1, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
      osc.start(t);
      osc.stop(t + 0.05);
    }
    this.triggerHaptic(ImpactStyle.Light);
  }

  playTap() {
    if (this.soundEnabled) {
      const ctx = this.getCtx();
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.setValueAtTime(400, t);
      gain.gain.setValueAtTime(0.05, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
      osc.start(t);
      osc.stop(t + 0.03);
    }
    this.triggerHaptic(ImpactStyle.Light);
