      gain.connect(ctx.destination);
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(300, t);
      osc.frequency.linearRampToValueAtTime(600, t + 0.1);
      gain.gain.setValueAtTime(0.1, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
      osc.start(t);
      osc.stop(t + 0.1);
    }
    this.triggerHaptic(ImpactStyle.Medium);
  }

  playZap() {
    if (this.soundEnabled) {
      const ctx = this.getCtx();
      const now = ctx.currentTime;
      const bubbleCount = 8;
      const spacing = 0.035;
      for (let i = 0; i < bubbleCount; i++) {
        const startTime = now + (i * spacing);
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        const startFreq = 300 + (i * 120);
        const endFreq = startFreq * 2.2;
        osc.frequency.setValueAtTime(startFreq, startTime);
        osc.frequency.exponentialRampToValueAtTime(endFreq, startTime + 0.08);
        const volume = 0.05 + (i / bubbleCount) * 0.4;
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(volume, startTime + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.1);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.15);
      }
    }
    if (this.vibrationEnabled) {
      setTimeout(() => {
        this.triggerHaptic(ImpactStyle.Medium);
      }, 250);
    }
  }

  playWin() {
    if (this.soundEnabled) {
      const ctx = this.getCtx();
      const t = ctx.currentTime;
      const notes = [523.25, 659.25, 783.99, 1046.50];
      notes.forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.value = freq;
        const start = t + i * 0.1;
        gain.gain.setValueAtTime(0, start);
        gain.gain.linearRampToValueAtTime(0.1, start + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.001, start + 0.5);
        osc.start(start);
        osc.stop(start + 0.5);
