import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

class SoundManager {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private profileId: string = 'snd-zen';

    constructor() {}

    private getCtx(): AudioContext {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContextClass();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        this.profileId = profileId;
    }

    // Generic tone player
    private playTone(freq: number, type: OscillatorType, duration: number, vol: number = 0.1, startTime: number = 0) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = startTime || ctx.currentTime;
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = type;
            osc.frequency.setValueAtTime(freq, t);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(vol, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + duration);

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start(t);
            osc.stop(t + duration + 0.1);
        } catch (e) {
            console.warn("Audio play failed", e);
        }
    }

    playClick() {
        if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Light });
        this.playTone(600, 'sine', 0.05, 0.05);
    }

    playTap() {
        if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Light });
        this.playTone(400, 'sine', 0.03, 0.03);
    }

    playPop() {
        if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Medium });
        this.playTone(500, 'triangle', 0.1, 0.1);
    }

    playWin() {
        if (this.vibrationEnabled) Haptics.notification({ type: NotificationType.Success });
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();
        const now = ctx.currentTime;
        [523.25, 659.25, 783.99, 1046.50].forEach((f, i) => {
            this.playTone(f, 'sine', 0.3, 0.1, now + i * 0.1);
        });
    }

    playLevelEnter() {
        this.playTone(440, 'sine', 0.2, 0.05);
    }

    playProgressFill(duration: number) {
        if (!this.soundEnabled) return () => {};
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.frequency.setValueAtTime(200, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + duration);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);

            osc.start();

            return () => {
                try {
                    gain.gain.setTargetAtTime(0, ctx.currentTime, 0.05);
                    osc.stop(ctx.currentTime + 0.1);
                } catch(e) {}
            };
        } catch (e) {
            return () => {};
        }
    }

    playUnlockReady() {
        if (this.vibrationEnabled) Haptics.notification({ type: NotificationType.Success });
        this.playTone(880, 'sine', 0.2, 0.1);
    }

    playPreview(packId: string) {
        this.playTone(440, 'sine', 0.2, 0.1);
    }

    playNumber(num: number) {
        const base = 261.63; 
        const freq = base * Math.pow(1.05946, (num - 1) * 2);
        this.playTone(freq, 'sine', 0.1, 0.1);
        if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Light });
    }

    playScan() {
        if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Heavy });
        this.playTone(150, 'sawtooth', 0.3, 0.05);
    }

    playReveal() {
        if (this.vibrationEnabled) Haptics.notification({ type: NotificationType.Warning });
        this.playTone(1200, 'sine', 0.3, 0.1);
    }

    playZap() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;

            const bubbles = [
                { start: 300, end: 500, delay: 0, vol: 0.15 },
                { start: 400, end: 700, delay: 0.04, vol: 0.12 },
                { start: 550, end: 900, delay: 0.08, vol: 0.1 }
            ];

            bubbles.forEach(b => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                const t = now + b.delay;

                osc.type = 'sine';

                osc.frequency.setValueAtTime(b.start, t);
                osc.frequency.exponentialRampToValueAtTime(b.end, t + 0.12);

                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(b.vol, t + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);

                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.start(t);
                osc.stop(t + 0.15);
            });
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
            setTimeout(() => {
                 if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Medium });
            }, 80);
        }
    }

    playCounterTick() {
        this.playTone(800, 'square', 0.03, 0.02);
    }

    playBubblePop() {
        this.playTone(300, 'sine', 0.1, 0.1);
    }

    playPepinoTap() {
        this.playTone(600, 'sine', 0.1, 0.1);
    }
}

