        if (isPerfectGame) {
            data.stats.perfectGames += 1;
        }
    }

    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };

    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];
           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1,
           };
           saveData(data);
      }
  },

  resetAllData: async () => {
    localStorage.removeItem(STORAGE_KEY);
    // Also remove legacy just in case
    localStorage.removeItem(LEGACY_STORAGE_KEY);

    try {
        await Preferences.remove({ key: STORAGE_KEY });
        await Preferences.remove({ key: LEGACY_STORAGE_KEY });
    } catch (e) {
        console.warn("Error removing native preference", e);
    }
  },

  getCompletedCount: (difficulty: string, maxLevel: number = 200): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  // PEPINO (Fish) Methods
  getPepinoState: (): PepinoState => {
      const data = getStoredData();
      return data.pepino || { unlocked: false, hasPendingGift: false };
  },

  unlockPepino: () => {
      const data = getStoredData();
      data.pepino = { 
          unlocked: true, 
          hasPendingGift: true, // First gift instant
          unlockedAt: Date.now() 
      };
      saveData(data);
  },

  grantPepinoGift: () => {
      const data = getStoredData();
      if (data.pepino && data.pepino.unlocked) {
          data.pepino.hasPendingGift = true;
          saveData(data);
      }
  },

  claimPepinoGift: () => {
      const data = getStoredData();
      if (data.pepino) {
          data.pepino.hasPendingGift = false;
          saveData(data);
      }
  },

  // STRICT MODE WARNING
  hasSeenStrictModeWarning: (): boolean => {
      return !!getStoredData().hasSeenStrictModeWarning;
  },

  setSeenStrictModeWarning: () => {
      const data = getStoredData();
      data.hasSeenStrictModeWarning = true;
      saveData(data);
  },
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Difficulty, LevelProgress } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';
import { AnimatedNumber } from '../ui/AnimatedNumber';
import { sounds } from '../../utils/sound';
import { motion, AnimatePresence } from 'framer-motion';

// --- OPTIMIZED LEVEL BUTTON COMPONENT ---
interface LevelButtonProps {
    levelId: number;
    status?: 'locked' | 'not-started' | 'in-progress' | 'completed';
    bestTime?: number;
    isGlobalBest: boolean;
    onSelect: (levelId: number) => void;
}

const LevelButton = React.memo(({ levelId, status, bestTime, isGlobalBest, onSelect }: LevelButtonProps) => {
    const isSolved = bestTime !== undefined || status === 'completed';
    const isInProgress = status === 'in-progress';

    let buttonClass = 'aspect-square rounded-xl relative transition-all active:scale-90 shadow-sm ';

    if (isSolved) {
        buttonClass += 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5 ';
        if (isInProgress) {
            buttonClass += '!ring-2 !ring-blue-400 !text-t-primary ';
        }
    } else if (isInProgress) {
        buttonClass += 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary ';
    } else {
        buttonClass += 'bg-t-surface hover:shadow-md text-t-primary ';
    }

    return (
        <button onClick={() => onSelect(levelId)} className={buttonClass}>
            <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{levelId}</span></div>
            {bestTime ? (
                isGlobalBest ? (
                    <>
                        <div className="absolute top-1.5 inset-x-0 flex justify-center">
                            <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                        </div>
                        <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                            <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                        </div>
                    </>
                ) : (
                    <div className="absolute bottom-1.5 inset-x-0 text-center">
                        <span className={`text-[10px] font-bold tracking-tight block ${isInProgress ? 'text-t-primary' : 'text-t-secondary'}`}>{formatTimeShort(bestTime)}</span>
                    </div>
                )
            ) : null}
        </button>
    );
});

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // --- BATCH DATA LOADING ---
    const [progressMap] = useState(() => Storage.getStoredData().progress);

    // --- TAB STATE ---
    const [activeTab, setActiveTab] = useState<1 | 2 | 3>(1);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    // Toast State
    const [showStrictModeToast, setShowStrictModeToast] = useState(false);

    // Reset scroll on tab change
    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollTop = 0;
        }
    }, [activeTab]);

    // Check for Strict Mode Warning
    useEffect(() => {
        const isStrict = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        if (isStrict && !Storage.hasSeenStrictModeWarning()) {
            setShowStrictModeToast(true);
            Storage.setSeenStrictModeWarning();
            const t = setTimeout(() => setShowStrictModeToast(false), 4000);
            return () => clearTimeout(t);
        }
    }, [difficulty]);

    // --- CALCULATE STATS ---
    const { globalBest, completedRange1, completedRange2 } = useMemo(() => {
        let best = Infinity;
        let c1 = 0;
        let c2 = 0;

        for (let i = 1; i <= 300; i++) {
            const key = `${difficulty}-${i}`;
            const p = progressMap[key];
            if (p && (p.status === 'completed' || p.bestTime !== undefined)) {
                if (i <= 100) c1++;
                else if (i <= 200) c2++;

                if (p.bestTime !== undefined && p.bestTime < best) {
                    best = p.bestTime;
                }
            }
        }

        return { 
            globalBest: best === Infinity ? undefined : best, 
            completedRange1: c1, 
            completedRange2: c2 
        };
    }, [progressMap, difficulty]);

    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    // Determine Visible Tabs: Pack 1 & 2 always visible. Pack 3 only if Pack 2 unlocked.
    const visibleTabs = [1, 2];
    if (isPack2Unlocked) visibleTabs.push(3);

    const handleTabChange = (tab: 1 | 2 | 3) => {
        sounds.playClick();
        setActiveTab(tab);
    };

    const renderContent = () => {
        if (activeTab === 1) {
            const levels = Array.from({ length: 100 }, (_, i) => i + 1);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 2) {
            if (!isPack2Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={101}
                            endLevel={200}
                            completedCount={completedRange1}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 2)}
                            onUnlock={onUnlockPack2}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 101);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6 animate-fade-in">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 3) {
            if (!isPack3Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={201}
                            endLevel={300}
                            completedCount={completedRange2}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 3)}
                            onUnlock={onUnlockPack3}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 201);
            return (
                <div className="flex flex-col items-center w-full max-w-md animate-fade-in">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden relative">
            <div className="w-full max-w-md flex flex-col items-center px-6 pt-4 shrink-0 z-20 gap-4">

                {/* Header Row */}
                <div className="w-full flex items-center justify-between relative">
                    <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                        <Icons.Back className="w-6 h-6 text-t-icon" />
                    </button>

                    <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                        <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                        <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                        {globalBest !== undefined && (
                            <div className="flex flex-col items-center animate-fade-in mt-1">
                                <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                            </div>
                        )}
                    </div>

                    <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm relative z-30">
                        <AnimatedNumber value={points} className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5" />
                        <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                    </div>
                </div>

                {/* Tab Navigation (Scrollable Pills) */}
                <div className="w-full overflow-x-auto hide-scrollbar touch-pan-x pb-2 pt-1 -mx-6 px-6">
                    <div className="flex gap-3 min-w-min mx-auto md:mx-0">
                        {visibleTabs.map((tabNum) => {
                            const isActive = activeTab === tabNum;
                            // Only confirm lock if it's strictly the next unavailable one
                            const isLocked = (tabNum === 2 && !isPack2Unlocked) || (tabNum === 3 && !isPack3Unlocked);

                            return (
                                <button
                                    key={tabNum}
                                    onClick={() => handleTabChange(tabNum as 1|2|3)}
                                    className={`
                                        px-6 py-2.5 rounded-full text-xs font-bold transition-all flex items-center justify-center gap-2 whitespace-nowrap shadow-sm border
                                        ${isActive 
                                            ? 'bg-stone-800 border-stone-800 text-white dark:bg-stone-100 dark:border-stone-100 dark:text-stone-900 scale-105' 
                                            : 'bg-white border-stone-200 text-stone-500 dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 hover:border-stone-300 dark:hover:border-stone-600'
                                        }
                                    `}
                                >
                                    {isLocked && <Icons.Lock className="w-3 h-3 opacity-60" />}
                                    <span>Pack {tabNum}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Scrollable Content Area */}
            <div 
                ref={scrollContainerRef}
                className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative"
            >
                {renderContent()}
                <div className="h-safe-bottom w-full shrink-0" />
            </div>

            {/* Strict Mode Toast Notification */}
            <AnimatePresence>
                {showStrictModeToast && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        transition={{ duration: 0.3 }}
                        className="absolute inset-0 flex items-center justify-center z-50 pointer-events-none px-8"
                    >
                        <div className="bg-stone-900/85 dark:bg-stone-100/85 backdrop-blur-md text-white dark:text-stone-900 p-5 rounded-2xl shadow-2xl flex flex-col items-center text-center gap-3 border border-white/10 dark:border-stone-200/50 max-w-sm">
                            <p className="text-sm font-semibold leading-relaxed">
                                Errors will not be revealed automatically
                            </p>
                            <div className="flex items-center gap-2 text-xs font-bold bg-white/10 dark:bg-black/5 px-3 py-1.5 rounded-full">
                                <span>Use</span>
                                <div className="flex items-center gap-1 text-red-400 dark:text-red-500">
                                    <Icons.Scan className="w-4 h-4" />
                                    <span>Scan</span>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export enum Difficulty {
  SuperEasy = 'Super Easy',
  Easy = 'Easy',
  Normal = 'Normal',
  Hard = 'Hard',
  Intense = 'Intense',
  Impossible = 'Impossible',
}

export type CellValue = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 | null;

export interface Cell {
  row: number;
  col: number;
  value: CellValue;
  isFixed: boolean;
  notes: number[];
  isError?: boolean;
  isMarkedWrong?: boolean; // For Scan skill
  isRevealed?: boolean; // For Reveal skill
}

export type Board = Cell[][];

export interface MoveLogEntry {
  r: number;
  c: number;
  v: number;
  t: number;
}

export interface LevelProgress {
  levelId: number; // 1 to 30
  difficulty: Difficulty;
  status: 'locked' | 'not-started' | 'in-progress' | 'completed';
  timeElapsed: number;
  lastPlayed?: number; // timestamp
  boardState?: Cell[][]; // simplified for storage
  moveLog?: MoveLogEntry[]; // History of moves for replay
  bestTime?: number; // Personal best time in seconds
  scanUses?: number; // Remaining scan uses
  revealUses?: number; // Remaining reveal uses
}

export interface AppSettings {
  sound: boolean;
  highlight: boolean;
  autoEraseNotes: boolean; // Default ON
  vibration: boolean;
  showTimer: boolean;
  appearance: 'system' | 'light' | 'dark';
  digitFirst: boolean; // Input mode
  screenWakeLock: boolean; // Keep screen on
  generateReplay: boolean; // Generate video replay on completion
  hiddenDifficulties: Difficulty[]; // List of difficulties to hide from main screen
}

export interface PepinoState {
  unlocked: boolean;
  hasPendingGift: boolean;
  unlockedAt?: number; // Timestamp of when it was unlocked, for intro logic
}

export interface StoredData {
  settings: AppSettings;
  points: number;
  progress: Record<string, LevelProgress>; // key: "Difficulty-LevelID"
  purchasedBackgrounds: string[];
  selectedBackground: string | null;
  purchasedNumberColors: string[];
  selectedNumberColor: string;
  purchasedSkills: string[];
  enabledSkills: string[]; // Tracks which skills are toggled ON for the game
  purchasedSoundPacks: string[];
  selectedSoundPack: string;
  bonusClaimed?: boolean;
  nextBonusClaimTime?: number; // Timestamp for next daily bonus
  starterPackPurchased?: boolean;
  unlockedPack2?: string[]; // Array of difficulty names where Pack 2 (levels 101-200) is unlocked
  unlockedPack3?: string[]; // Array of difficulty names where Pack 3 (levels 201-300) is unlocked
  pepino?: PepinoState;
  hasSeenStrictModeWarning?: boolean; // Track if user has seen the hard mode warning

  // Stats
  stats?: {
      totalGamesWon: number;
      totalDiamondsEarned: number;
      perfectGames: number; // Won without errors
  };
}

export type DiamondOffer = {
  id: string;
  productId: string; // Apple/Google Store Product ID
  title: string;
  subtitle?: string;
  diamonds: number;
  includes?: string[];
  badge?: string;
  priceLabel: string;
  type: "starter" | "pack" | "support";
  gradientClass?: string;
};

import { AppSettings, LevelProgress, StoredData, PepinoState, Difficulty } from '../types';
import { Preferences } from '@capacitor/preferences';

const STORAGE_KEY = 'oku_data_v1';
const LEGACY_STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  sound: true,
  highlight: true,
  autoEraseNotes: true, // Default ON
  vibration: true,
  showTimer: true,
  appearance: 'light',
  digitFirst: false, // Default OFF
  screenWakeLock: false, // Default OFF
  generateReplay: true, // Default ON
  hiddenDifficulties: [], // Default show all
};

const DEFAULT_STATS = {
    totalGamesWon: 0,
    totalDiamondsEarned: 0,
    perfectGames: 0
};

function getStoredData(): StoredData {
  try {
    let raw = localStorage.getItem(STORAGE_KEY);

    // Migration Logic: Check for legacy key if new key doesn't exist
    if (!raw) {
        const legacyRaw = localStorage.getItem(LEGACY_STORAGE_KEY);
        if (legacyRaw) {
            raw = legacyRaw;
            // Persist migration immediately
            localStorage.setItem(STORAGE_KEY, legacyRaw);
        }
    }

    if (!raw) {
      const initialData: StoredData = { 
          settings: DEFAULT_SETTINGS, 
          points: 0, 
          progress: {},
          purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
          selectedBackground: 'bg-default',
          purchasedNumberColors: ['num-default'],
          selectedNumberColor: 'num-default',
          purchasedSkills: [],
          enabledSkills: [],
          purchasedSoundPacks: ['snd-zen'],
          selectedSoundPack: 'snd-zen',
          bonusClaimed: false,
          nextBonusClaimTime: 0,
          starterPackPurchased: false,
          unlockedPack2: [],
          unlockedPack3: [],
          pepino: { unlocked: false, hasPendingGift: false },
          hasSeenStrictModeWarning: false,
          stats: DEFAULT_STATS
      };

      return initialData;
    }
    const data = JSON.parse(raw);

    // Migrations
    if (typeof data.points !== 'number') data.points = 0;

    if (!data.purchasedBackgrounds) data.purchasedBackgrounds = ['bg-default', 'bg-dyn-default'];
    if (!data.purchasedBackgrounds.includes('bg-default')) data.purchasedBackgrounds.push('bg-default');
    if (!data.purchasedBackgrounds.includes('bg-dyn-default')) data.purchasedBackgrounds.push('bg-dyn-default');

    if (data.selectedBackground === undefined) data.selectedBackground = 'bg-default';

    if (!data.purchasedNumberColors) data.purchasedNumberColors = ['num-default'];
    if (!data.selectedNumberColor) data.selectedNumberColor = 'num-default';

    if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
    if (!data.selectedSoundPack) data.selectedSoundPack = 'snd-zen';

    if (data.settings.vibration === undefined) data.settings.vibration = true;

    if (data.settings.showTimer === undefined) {
        if ((data.settings as any).hideTimer !== undefined) {
            data.settings.showTimer = !(data.settings as any).hideTimer;
            delete (data.settings as any).hideTimer;
        } else {
            data.settings.showTimer = true;
        }
    }

    if (data.settings.autoEraseNotes === undefined) data.settings.autoEraseNotes = true;
    if (data.settings.digitFirst === undefined) data.settings.digitFirst = false;
    if (data.settings.screenWakeLock === undefined) data.settings.screenWakeLock = false;
    if (data.settings.generateReplay === undefined) data.settings.generateReplay = true; // Default ON
    if (data.settings.hiddenDifficulties === undefined) data.settings.hiddenDifficulties = [];

    if (data.settings.appearance === undefined) {
        data.settings.appearance = 'light'; 
    }

    if (!data.purchasedSkills) data.purchasedSkills = [];
    if (!data.enabledSkills) data.enabledSkills = [...data.purchasedSkills]; // Default new field to existing purchased skills

    if (data.bonusClaimed === undefined) data.bonusClaimed = false;
    if (data.nextBonusClaimTime === undefined) data.nextBonusClaimTime = 0;

    if (data.starterPackPurchased === undefined) data.starterPackPurchased = false;

    if (!data.unlockedPack2) data.unlockedPack2 = [];
    if (!data.unlockedPack3) data.unlockedPack3 = [];

    if (!data.pepino) {
        data.pepino = { unlocked: false, hasPendingGift: false };
    } else {
        // Migration from Timer based (lastGiftTime) to Event based (hasPendingGift)
        if ((data.pepino as any).nextGiftDelay !== undefined) {
            const old = data.pepino as any;
            const wasReady = Date.now() >= (old.lastGiftTime || 0) + (old.nextGiftDelay || 0);
            data.pepino = {
                unlocked: old.unlocked,
                hasPendingGift: wasReady,
                unlockedAt: old.unlocked ? Date.now() : undefined // Fallback unlock time
            };
        }
    }

    if (!data.stats) {
        // Simple backfill of totalGamesWon based on progress
        const wonCount = Object.values(data.progress || {}).filter((p: any) => p.status === 'completed' || p.bestTime !== undefined).length;
        data.stats = { ...DEFAULT_STATS, totalGamesWon: wonCount };
    }

    if (data.hasSeenStrictModeWarning === undefined) data.hasSeenStrictModeWarning = false;

    // Clean up deprecated fields if they exist from previous versions
    if ((data as any).purchasedBundles) delete (data as any).purchasedBundles;

    return data;
  } catch (e) {
    console.error("Failed to load data", e);
    return { 
        settings: DEFAULT_SETTINGS, 
        points: 0, 
        progress: {},
        purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
        selectedBackground: 'bg-default',
        purchasedNumberColors: ['num-default'],
        selectedNumberColor: 'num-default',
        purchasedSkills: [],
        enabledSkills: [],
        purchasedSoundPacks: ['snd-zen'],
        selectedSoundPack: 'snd-zen',
        bonusClaimed: false,
        nextBonusClaimTime: 0,
        starterPackPurchased: false,
        unlockedPack2: [],
        unlockedPack3: [],
        pepino: { unlocked: false, hasPendingGift: false },
        hasSeenStrictModeWarning: false,
        stats: DEFAULT_STATS
    };
  }
}

async function saveData(data: StoredData) {
  try {
    const stringified = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, stringified);
    await Preferences.set({
        key: STORAGE_KEY,
        value: stringified
    }).catch((err: any) => console.error("Native save failed", err));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getStoredData, 

  initializeNative: async (): Promise<StoredData | null> => {
      try {
          let { value } = await Preferences.get({ key: STORAGE_KEY });

          // Native Migration Logic
          if (!value) {
              const legacy = await Preferences.get({ key: LEGACY_STORAGE_KEY });
              if (legacy.value) {
                  value = legacy.value;
                  // Persist to new key
                  await Preferences.set({ key: STORAGE_KEY, value: legacy.value });
              }
          }

          if (value) {
              localStorage.setItem(STORAGE_KEY, value);
              return JSON.parse(value);
          }
          return null;
      } catch (e) {
          console.warn("Could not read native prefs", e);
          return null;
      }
  },

  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getPoints: (): number => {
    return getStoredData().points;
  },

  addPoints: (amount: number) => {
    const data = getStoredData();
    data.points += amount;
    // Update stats
    if (!data.stats) data.stats = { totalGamesWon: 0, totalDiamondsEarned: 0, perfectGames: 0 };
    data.stats.totalDiamondsEarned += amount;

    saveData(data);
    return data.points;
  },

  getPurchasedBackgrounds: (): string[] => {
      return getStoredData().purchasedBackgrounds;
  },

  getSelectedBackground: (): string | null => {
      return getStoredData().selectedBackground;
  },

  purchaseBackground: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedBackgrounds.includes(id)) {
          data.points -= cost;
          data.purchasedBackgrounds.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectBackground: (id: string | null) => {
      const data = getStoredData();
      data.selectedBackground = id;
      saveData(data);
  },

  getPurchasedNumberColors: (): string[] => {
      return getStoredData().purchasedNumberColors;
  },

  getSelectedNumberColor: (): string => {
      return getStoredData().selectedNumberColor;
  },

  purchaseNumberColor: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedNumberColors.includes(id)) {
          data.points -= cost;
          data.purchasedNumberColors.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectNumberColor: (id: string) => {
      const data = getStoredData();
      data.selectedNumberColor = id;
      saveData(data);
  },

  getPurchasedSoundPacks: (): string[] => {
    return getStoredData().purchasedSoundPacks || ['snd-zen'];
  },

  getSelectedSoundPack: (): string => {
      return getStoredData().selectedSoundPack || 'snd-zen';
  },

  purchaseSoundPack: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
      if (data.points >= cost && !data.purchasedSoundPacks.includes(id)) {
          data.points -= cost;
          data.purchasedSoundPacks.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectSoundPack: (id: string) => {
      const data = getStoredData();
      data.selectedSoundPack = id;
      saveData(data);
  },

  getPurchasedSkills: (): string[] => {
      return getStoredData().purchasedSkills;
  },

  getEnabledSkills: (): string[] => {
    const data = getStoredData();
    return data.enabledSkills || [];
  },

  purchaseSkill: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedSkills.includes(id)) {
          data.points -= cost;
          data.purchasedSkills.push(id);
          if (!data.enabledSkills) data.enabledSkills = [];
          if (!data.enabledSkills.includes(id)) data.enabledSkills.push(id); // Auto enable on purchase
          saveData(data);
          return true;
      }
      return false;
  },

  toggleSkillEnabled: (id: string) => {
    const data = getStoredData();
    if (!data.enabledSkills) data.enabledSkills = [];
    if (data.enabledSkills.includes(id)) {
      data.enabledSkills = data.enabledSkills.filter(s => s !== id);
    } else if (data.purchasedSkills.includes(id)) {
      data.enabledSkills.push(id);
    }
    saveData(data);
    return data.enabledSkills;
  },

  isBonusClaimed: (): boolean => {
      return !!getStoredData().bonusClaimed;
  },

  setBonusClaimed: () => {
      const data = getStoredData();
      data.bonusClaimed = true;
      saveData(data);
  },

  getNextBonusClaimTime: (): number => {
      return getStoredData().nextBonusClaimTime || 0;
  },

  setNextBonusClaimTime: (time: number) => {
      const data = getStoredData();
      data.nextBonusClaimTime = time;
      saveData(data);
  },

  isStarterPackPurchased: (): boolean => {
      return !!getStoredData().starterPackPurchased;
  },

  setStarterPackPurchased: () => {
      const data = getStoredData();
      data.starterPackPurchased = true;
      saveData(data);
  },

  getUnlockedPacks2: (): string[] => {
      return getStoredData().unlockedPack2 || [];
  },

  isPack2Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack2?.includes(difficulty) ?? false;
  },

  unlockPack2: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack2) data.unlockedPack2 = [];

      if (data.points >= cost && !data.unlockedPack2.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack2.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getUnlockedPacks3: (): string[] => {
      return getStoredData().unlockedPack3 || [];
  },

  isPack3Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack3?.includes(difficulty) ?? false;
  },

  unlockPack3: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack3) data.unlockedPack3 = [];

      if (data.points >= cost && !data.unlockedPack3.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack3.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress, isPerfectGame: boolean = false) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    const existing = data.progress[key];
    let bestTime = existing?.bestTime;

    if (progress.status === 'completed') {
        if (bestTime === undefined || progress.timeElapsed < bestTime) {
            bestTime = progress.timeElapsed;
        }
        // Increment Stats
        if (!data.stats) data.stats = { totalGamesWon: 0, totalDiamondsEarned: 0, perfectGames: 0 };

        data.stats.totalGamesWon += 1;

        if (isPerfectGame) {
            data.stats.perfectGames += 1;
        }
    }

    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };

    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];
           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1,
           };
           saveData(data);
      }
  },

  resetAllData: async () => {
    localStorage.removeItem(STORAGE_KEY);
    // Also remove legacy just in case
    localStorage.removeItem(LEGACY_STORAGE_KEY);

    try {
        await Preferences.remove({ key: STORAGE_KEY });
        await Preferences.remove({ key: LEGACY_STORAGE_KEY });
    } catch (e) {
        console.warn("Error removing native preference", e);
    }
  },

  getCompletedCount: (difficulty: string, maxLevel: number = 200): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  // PEPINO (Fish) Methods
  getPepinoState: (): PepinoState => {
      const data = getStoredData();
      return data.pepino || { unlocked: false, hasPendingGift: false };
  },

  unlockPepino: () => {
      const data = getStoredData();
      data.pepino = { 
          unlocked: true, 
          hasPendingGift: true, // First gift instant
          unlockedAt: Date.now() 
      };
      saveData(data);
  },

  grantPepinoGift: () => {
      const data = getStoredData();
      if (data.pepino && data.pepino.unlocked) {
          data.pepino.hasPendingGift = true;
          saveData(data);
      }
  },

  claimPepinoGift: () => {
      const data = getStoredData();
      if (data.pepino) {
          data.pepino.hasPendingGift = false;
          saveData(data);
      }
  },

  // STRICT MODE WARNING
  hasSeenStrictModeWarning: (): boolean => {
      return !!getStoredData().hasSeenStrictModeWarning;
  },

  setSeenStrictModeWarning: () => {
      const data = getStoredData();
      data.hasSeenStrictModeWarning = true;
      saveData(data);
  },
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Difficulty, LevelProgress } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';
import { AnimatedNumber } from '../ui/AnimatedNumber';
import { sounds } from '../../utils/sound';
import { motion, AnimatePresence } from 'framer-motion';

// --- OPTIMIZED LEVEL BUTTON COMPONENT ---
interface LevelButtonProps {
    levelId: number;
    status?: 'locked' | 'not-started' | 'in-progress' | 'completed';
    bestTime?: number;
    isGlobalBest: boolean;
    onSelect: (levelId: number) => void;
}

const LevelButton = React.memo(({ levelId, status, bestTime, isGlobalBest, onSelect }: LevelButtonProps) => {
    const isSolved = bestTime !== undefined || status === 'completed';
    const isInProgress = status === 'in-progress';

    let buttonClass = 'aspect-square rounded-xl relative transition-all active:scale-90 shadow-sm ';

    if (isSolved) {
        buttonClass += 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5 ';
        if (isInProgress) {
            buttonClass += '!ring-2 !ring-blue-400 !text-t-primary ';
        }
    } else if (isInProgress) {
        buttonClass += 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary ';
    } else {
        buttonClass += 'bg-t-surface hover:shadow-md text-t-primary ';
    }

    return (
        <button onClick={() => onSelect(levelId)} className={buttonClass}>
            <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{levelId}</span></div>
            {bestTime ? (
                isGlobalBest ? (
                    <>
                        <div className="absolute top-1.5 inset-x-0 flex justify-center">
                            <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                        </div>
                        <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                            <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                        </div>
                    </>
                ) : (
                    <div className="absolute bottom-1.5 inset-x-0 text-center">
                        <span className={`text-[10px] font-bold tracking-tight block ${isInProgress ? 'text-t-primary' : 'text-t-secondary'}`}>{formatTimeShort(bestTime)}</span>
                    </div>
                )
            ) : null}
        </button>
    );
});

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // --- BATCH DATA LOADING ---
    const [progressMap] = useState(() => Storage.getStoredData().progress);

    // --- TAB STATE ---
    const [activeTab, setActiveTab] = useState<1 | 2 | 3>(1);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    // Toast State
    const [showStrictModeToast, setShowStrictModeToast] = useState(false);

    // Reset scroll on tab change
    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollTop = 0;
        }
    }, [activeTab]);

    // Check for Strict Mode Warning
    useEffect(() => {
        const isStrict = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        if (isStrict && !Storage.hasSeenStrictModeWarning()) {
            setShowStrictModeToast(true);
            Storage.setSeenStrictModeWarning();
            const t = setTimeout(() => setShowStrictModeToast(false), 4000);
            return () => clearTimeout(t);
        }
    }, [difficulty]);

    // --- CALCULATE STATS ---
    const { globalBest, completedRange1, completedRange2 } = useMemo(() => {
        let best = Infinity;
        let c1 = 0;
        let c2 = 0;

        for (let i = 1; i <= 300; i++) {
            const key = `${difficulty}-${i}`;
            const p = progressMap[key];
            if (p && (p.status === 'completed' || p.bestTime !== undefined)) {
                if (i <= 100) c1++;
                else if (i <= 200) c2++;

                if (p.bestTime !== undefined && p.bestTime < best) {
                    best = p.bestTime;
                }
            }
        }

        return { 
            globalBest: best === Infinity ? undefined : best, 
            completedRange1: c1, 
            completedRange2: c2 
        };
    }, [progressMap, difficulty]);

    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    // Determine Visible Tabs: Pack 1 & 2 always visible. Pack 3 only if Pack 2 unlocked.
    const visibleTabs = [1, 2];
    if (isPack2Unlocked) visibleTabs.push(3);

    const handleTabChange = (tab: 1 | 2 | 3) => {
        sounds.playClick();
        setActiveTab(tab);
    };

    const renderContent = () => {
        if (activeTab === 1) {
            const levels = Array.from({ length: 100 }, (_, i) => i + 1);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 2) {
            if (!isPack2Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={101}
                            endLevel={200}
                            completedCount={completedRange1}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 2)}
                            onUnlock={onUnlockPack2}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 101);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6 animate-fade-in">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 3) {
            if (!isPack3Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={201}
                            endLevel={300}
                            completedCount={completedRange2}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 3)}
                            onUnlock={onUnlockPack3}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 201);
            return (
                <div className="flex flex-col items-center w-full max-w-md animate-fade-in">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden relative">
            <div className="w-full max-w-md flex flex-col items-center px-6 pt-4 shrink-0 z-20 gap-4">

                {/* Header Row */}
                <div className="w-full flex items-center justify-between relative">
                    <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                        <Icons.Back className="w-6 h-6 text-t-icon" />
                    </button>

                    <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                        <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                        <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                        {globalBest !== undefined && (
                            <div className="flex flex-col items-center animate-fade-in mt-1">
                                <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                            </div>
                        )}
                    </div>

                    <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm relative z-30">
                        <AnimatedNumber value={points} className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5" />
                        <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                    </div>
                </div>

                {/* Tab Navigation (Scrollable Pills) */}
                <div className="w-full overflow-x-auto hide-scrollbar touch-pan-x pb-2 pt-1 -mx-6 px-6">
                    <div className="flex gap-3 min-w-min mx-auto md:mx-0">
                        {visibleTabs.map((tabNum) => {
                            const isActive = activeTab === tabNum;
                            // Only confirm lock if it's strictly the next unavailable one
                            const isLocked = (tabNum === 2 && !isPack2Unlocked) || (tabNum === 3 && !isPack3Unlocked);

                            return (
                                <button
                                    key={tabNum}
                                    onClick={() => handleTabChange(tabNum as 1|2|3)}
                                    className={`
                                        px-6 py-2.5 rounded-full text-xs font-bold transition-all flex items-center justify-center gap-2 whitespace-nowrap shadow-sm border
                                        ${isActive 
                                            ? 'bg-stone-800 border-stone-800 text-white dark:bg-stone-100 dark:border-stone-100 dark:text-stone-900 scale-105' 
                                            : 'bg-white border-stone-200 text-stone-500 dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 hover:border-stone-300 dark:hover:border-stone-600'
                                        }
                                    `}
                                >
                                    {isLocked && <Icons.Lock className="w-3 h-3 opacity-60" />}
                                    <span>Pack {tabNum}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Scrollable Content Area */}
            <div 
                ref={scrollContainerRef}
                className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative"
            >
                {renderContent()}
                <div className="h-safe-bottom w-full shrink-0" />
            </div>

            {/* Strict Mode Toast Notification */}
            <AnimatePresence>
                {showStrictModeToast && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        transition={{ duration: 0.3 }}
                        className="absolute inset-0 flex items-center justify-center z-50 pointer-events-none px-8"
                    >
                        <div className="bg-stone-900/50 dark:bg-stone-100/50 backdrop-blur-md text-white dark:text-stone-900 p-5 rounded-2xl shadow-2xl flex flex-col items-center text-center gap-3 border border-white/10 dark:border-stone-200/20 max-w-sm">
                            <p className="text-sm font-semibold leading-relaxed drop-shadow-md">
                                Errors will not be revealed automatically
                            </p>
                            <div className="flex items-center gap-2 text-xs font-bold bg-white/20 dark:bg-black/10 px-3 py-1.5 rounded-full backdrop-blur-sm">
                                <span>Use</span>
                                <div className="flex items-center gap-1 text-red-300 dark:text-red-600">
                                    <Icons.Scan className="w-4 h-4" />
                                    <span>Scan</span>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export enum Difficulty {
  SuperEasy = 'Super Easy',
  Easy = 'Easy',
  Normal = 'Normal',
  Hard = 'Hard',
  Intense = 'Intense',
  Impossible = 'Impossible',
}

export type CellValue = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 | null;

export interface Cell {
  row: number;
  col: number;
  value: CellValue;
  isFixed: boolean;
  notes: number[];
  isError?: boolean;
  isMarkedWrong?: boolean; // For Scan skill
  isRevealed?: boolean; // For Reveal skill
}

export type Board = Cell[][];

export interface MoveLogEntry {
  r: number;
  c: number;
  v: number;
  t: number;
}

export interface LevelProgress {
  levelId: number; // 1 to 30
  difficulty: Difficulty;
  status: 'locked' | 'not-started' | 'in-progress' | 'completed';
  timeElapsed: number;
  lastPlayed?: number; // timestamp
  boardState?: Cell[][]; // simplified for storage
  moveLog?: MoveLogEntry[]; // History of moves for replay
  bestTime?: number; // Personal best time in seconds
  scanUses?: number; // Remaining scan uses
  revealUses?: number; // Remaining reveal uses
}

export interface AppSettings {
  sound: boolean;
  highlight: boolean;
  autoEraseNotes: boolean; // Default ON
  vibration: boolean;
  showTimer: boolean;
  appearance: 'system' | 'light' | 'dark';
  digitFirst: boolean; // Input mode
  screenWakeLock: boolean; // Keep screen on
