    const scrollContainerRef = useRef<HTMLDivElement>(null);

    // Toast State
    const [showStrictModeToast, setShowStrictModeToast] = useState(false);

    // Reset scroll on tab change
    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollTop = 0;
        }
    }, [activeTab]);

    // Check for Strict Mode Warning
    useEffect(() => {
        const isStrict = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        if (isStrict && !Storage.hasSeenStrictModeWarning(difficulty)) {
            setShowStrictModeToast(true);
            Storage.setSeenStrictModeWarning(difficulty);

            // Disappear after 4 seconds
            const t = setTimeout(() => {
                setShowStrictModeToast(false);
            }, 4000);
            return () => clearTimeout(t);
        }
    }, [difficulty]);

    // --- CALCULATE STATS ---
    const { globalBest, completedRange1, completedRange2 } = useMemo(() => {
        let best = Infinity;
        let c1 = 0;
        let c2 = 0;

        for (let i = 1; i <= 300; i++) {
            const key = `${difficulty}-${i}`;
            const p = progressMap[key];
            if (p && (p.status === 'completed' || p.bestTime !== undefined)) {
                if (i <= 100) c1++;
                else if (i <= 200) c2++;

                if (p.bestTime !== undefined && p.bestTime < best) {
                    best = p.bestTime;
                }
            }
        }

        return { 
            globalBest: best === Infinity ? undefined : best, 
            completedRange1: c1, 
            completedRange2: c2 
        };
    }, [progressMap, difficulty]);

    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    // Determine Visible Tabs: Pack 1 & 2 always visible. Pack 3 only if Pack 2 unlocked.
    const visibleTabs = [1, 2];
    if (isPack2Unlocked) visibleTabs.push(3);

    const handleTabChange = (tab: 1 | 2 | 3) => {
        sounds.playClick();
        setActiveTab(tab);
    };

    const renderContent = () => {
        if (activeTab === 1) {
            const levels = Array.from({ length: 100 }, (_, i) => i + 1);
            return (
