                                            ? 'bg-stone-800 border-stone-800 text-white dark:bg-stone-100 dark:border-stone-100 dark:text-stone-900 scale-105' 
                                            : 'bg-white border-stone-200 text-stone-500 dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 hover:border-stone-300 dark:hover:border-stone-600'
                                        }
                                    `}
                                >
                                    {isLocked && <Icons.Lock className="w-3 h-3 opacity-60" />}
                                    <span>Pack {tabNum}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Scrollable Content Area */}
            <div 
                ref={scrollContainerRef}
                className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative"
            >
                {renderContent()}
                <div className="h-safe-bottom w-full shrink-0" />
            </div>

            {/* Strict Mode Toast Notification */}
            <AnimatePresence>
                {showStrictModeToast && (
                    <motion.div
                        key="strict-mode-toast"
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, transition: { duration: 1, ease: "easeOut" } }}
                        transition={{ duration: 0.3 }}
                        className="absolute inset-0 flex items-center justify-center z-50 pointer-events-none px-8"
                    >
                        <div className="bg-stone-900/50 dark:bg-stone-100/50 text-white dark:text-stone-900 py-3 px-5 rounded-2xl shadow-2xl flex flex-col items-center text-center gap-2 border border-white/10 dark:border-stone-200/20 max-w-sm backdrop-blur-md">
                            <p className="text-sm font-semibold leading-relaxed drop-shadow-md">
                                Errors will not be revealed automatically
                            </p>
                            <div className="flex items-center gap-2 text-xs font-bold bg-stone-200 dark:bg-stone-800 text-stone-600 dark:text-stone-300 px-3 py-1.5 rounded-full shadow-inner">
                                <span>Use</span>
                                <div className="flex items-center gap-1 text-red-500 dark:text-red-400">
                                    <Icons.Scan className="w-4 h-4" />
                                    <span>Scan</span>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

