import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

class SoundManager {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private currentProfile: string = 'snd-zen';

    constructor() {
        // Lazy init to avoid auto-play policy issues until user interaction
    }

    private getCtx(): AudioContext {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContextClass();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    public setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    public setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    public setProfile(profileId: string) {
        this.currentProfile = profileId;
    }

    // Helper to play a simple tone
    private playTone(freq: number, type: OscillatorType, duration: number, startTime: number = 0, vol: number = 0.1) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = type;
            osc.frequency.setValueAtTime(freq, ctx.currentTime + startTime);

            // Envelope to avoid clicking
            gain.gain.setValueAtTime(0, ctx.currentTime + startTime);
            gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + startTime + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + startTime + duration);

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start(ctx.currentTime + startTime);
            osc.stop(ctx.currentTime + startTime + duration + 0.1);
        } catch (e) {
            console.warn('Audio play failed', e);
        }
    }

    public playClick() {
        if (this.soundEnabled) {
            this.playTone(800, 'sine', 0.05, 0, 0.05);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light }).catch(() => {});
        }
    }

    public playTap() {
        if (this.soundEnabled) {
            this.playTone(600, 'triangle', 0.05, 0, 0.05);
        }
    }

    public playNumber(num: number) {
         if (this.soundEnabled) {
            const baseFreq = 300;
            const freq = baseFreq + (num * 30);
            this.playTone(freq, 'sine', 0.1, 0, 0.1);
        }
        if (this.vibrationEnabled) {
             Haptics.impact({ style: ImpactStyle.Light }).catch(() => {});
        }
    }

    public playPop() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(800, ctx.currentTime + 0.1);
            gain.gain.setValueAtTime(0.1, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.1);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium }).catch(() => {});
        }
    }

    public playWin() {
        if (this.soundEnabled) {
            const notes = [523.25, 659.25, 783.99, 1046.50];
            notes.forEach((freq, i) => {
                this.playTone(freq, 'sine', 0.3, i * 0.1, 0.2);
            });
        }
        if (this.vibrationEnabled) {
            Haptics.notification({ type: NotificationType.Success }).catch(() => {});
        }
    }

    public playLevelEnter() {
        if (this.soundEnabled) {
            this.playTone(440, 'sine', 0.2, 0, 0.1);
            this.playTone(554, 'sine', 0.2, 0.1, 0.1);
        }
    }

    public playScan() {
         if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(600, ctx.currentTime + 0.3);
            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.3);
         }
         if (this.vibrationEnabled) {
             Haptics.impact({ style: ImpactStyle.Heavy }).catch(() => {});
         }
    }

    public playReveal() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.2);
            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.2, ctx.currentTime + 0.1);
            gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.3);
        }
    }

    public playPreview(packId: string) {
        if (this.soundEnabled) {
            this.playTap();
            setTimeout(() => this.playNumber(5), 150);
        }
    }

    public playUnlockReady() {
        if (this.soundEnabled) {
             this.playTone(880, 'sine', 0.2, 0, 0.1);
             this.playTone(1108, 'sine', 0.4, 0.1, 0.1);
        }
    }

    public playCounterTick() {
        if (this.soundEnabled) {
            this.playTone(800, 'square', 0.02, 0, 0.02);
        }
    }

    public playBubblePop() {
         if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(600, ctx.currentTime + 0.1);
            gain.gain.setValueAtTime(0.2, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.1);
         }
    }

    public playPepinoTap() {
        if (this.soundEnabled) {
            this.playBubblePop();
        }
    }

    public playZap() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;

            // 1. The Bubble (Sine Up-sweep)
            const bubbleOsc = ctx.createOscillator();
            const bubbleGain = ctx.createGain();

            bubbleOsc.type = 'sine';
            bubbleOsc.frequency.setValueAtTime(350, now);
            bubbleOsc.frequency.exponentialRampToValueAtTime(800, now + 0.12);

            bubbleGain.gain.setValueAtTime(0, now);
            bubbleGain.gain.linearRampToValueAtTime(0.6, now + 0.01); 
            bubbleGain.gain.exponentialRampToValueAtTime(0.01, now + 0.12);

            bubbleOsc.connect(bubbleGain);
            bubbleGain.connect(ctx.destination);

            bubbleOsc.start(now);
            bubbleOsc.stop(now + 0.15);

            // 2. The Mechanism (Square Blip)
            const clickOsc = ctx.createOscillator();
            const clickGain = ctx.createGain();

            clickOsc.type = 'square';
            clickOsc.frequency.setValueAtTime(200, now);

            const clickFilter = ctx.createBiquadFilter();
            clickFilter.type = 'lowpass';
            clickFilter.frequency.value = 3000;

            clickGain.gain.setValueAtTime(0, now);
            clickGain.gain.linearRampToValueAtTime(0.15, now + 0.005);
            clickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);

            clickOsc.connect(clickFilter);
            clickFilter.connect(clickGain);
            clickGain.connect(ctx.destination);

            clickOsc.start(now);
            clickOsc.stop(now + 0.05);
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium }).catch(() => {});
        }
    }

    public playProgressFill(duration: number): () => void {
        if (!this.soundEnabled) return () => {};

        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = 'triangle';
            osc.frequency.setValueAtTime(200, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(600, ctx.currentTime + duration);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.05, ctx.currentTime + duration * 0.9);
            gain.gain.linearRampToValueAtTime(0, ctx.currentTime + duration);

            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + duration);

            return () => {
                try {
                    osc.stop();
                    osc.disconnect();
                } catch(e) {}
            };
        } catch (e) {
            return () => {};
        }
    }
}

export const sounds = new SoundManager();

public playZap() {
    if (this.soundEnabled) {
        const ctx = this.getCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(300, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(600, ctx.currentTime + 0.15);

        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + 0.15);
    }

    if (this.vibrationEnabled) {
        Haptics.impact({ style: ImpactStyle.Medium }).catch(() => {});
    }
}

