// Hook for 1.5s counter animation with sound feedback
const useStatCounter = (target: number, dependency: any) => {
    const [count, setCount] = useState(0);
    const lastSoundValue = useRef(0);

    useEffect(() => {
        let startTime: number | null = null;
        let animationFrame: number;

        // Reset state on dependency change
        setCount(0);
        lastSoundValue.current = 0;

        const animate = (time: number) => {
            if (!startTime) startTime = time;
            const progress = Math.min((time - startTime) / 1000, 1); // 1s duration for snappier feel

            // Ease Out Quart
            const ease = 1 - Math.pow(1 - progress, 4); 

            const currentRaw = target * ease;
            const currentInt = Math.floor(currentRaw);

            // Play ticking sound if the integer value has changed (throttled)
            if (currentInt !== lastSoundValue.current && currentInt % 5 === 0) {
               // sounds.playCounterTick(); // Optional: can get noisy with many stats
            }
            lastSoundValue.current = currentInt;

            setCount(currentRaw);

            if (progress < 1) {
                animationFrame = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };

        animationFrame = requestAnimationFrame(animate);

        return () => cancelAnimationFrame(animationFrame);
    }, [target, dependency]);

    return count;
};

