                              )}
                          </button>

                          {/* Stats - Pacific Brown */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStats(); }} 
                            style={{ width: '47.5%' }}
                            className={`p-4 ${PREMIUM_BROWN} rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:brightness-110 ${PREMIUM_BEIGE} group`}
                          >
                              <Icons.BarChart className="w-5 h-5 group-hover:scale-110 transition-transform" /> 
                              <span className="font-bold tracking-wide">Stats</span>
