                            style={{ width: '47.5%', background: GOLD_GRADIENT }}
                            className={`${COMMON_BTN_STYLE} ${GOLD_TEXT}`}
                          >
                              <Icons.Store className="w-5 h-5 group-hover:scale-110 transition-transform" /> 
                              <span className="font-bold tracking-wide">Market</span>
                          </button>

                          {/* Get More -> Diamonds - Gold with Diamond Loop & Sweep */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} 
                            style={{ width: '47.5%', background: GOLD_GRADIENT }}
                            className={`${COMMON_BTN_STYLE} ${GOLD_TEXT} relative overflow-visible shadow-md`}
                          >
                              {/* Pepino Badge - Pending Gift */}
