                                <div className="absolute -top-1.5 -right-1.5 z-50 animate-pop">
                                    <div className="w-[22px] h-[22px] bg-red-500 rounded-full flex items-center justify-center shadow-md animate-bounce">
                                        <Icons.Gift className="w-3.5 h-3.5 text-white" />
                                    </div>
                                </div>
                              )}

                              {/* 1. Moving Diamond Pattern (Upward Loop) */}
                              <div 
                                className="absolute inset-0 opacity-[0.08] pointer-events-none overflow-hidden rounded-2xl"
                                style={{
                                    backgroundImage: `url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M10 2 L18 10 L10 18 L2 10 Z' fill='none' stroke='%233f2e18' stroke-width='1.5'/%3E%3C/svg%3E")`,
                                    backgroundSize: '20px 20px',
                                    animation: 'diamond-scroll 3s linear infinite'
                                }}
                              />

                              {/* 2. Light Sweep (Shimmer) */}
                              <div className="absolute inset-0 -translate-x-full animate-[shimmer_4s_infinite] bg-gradient-to-r from-transparent via-white/40 to-transparent skew-x-[-20deg] pointer-events-none overflow-hidden rounded-2xl" />

                              {/* Content Layer (z-10) */}
                              <div className="relative z-10 flex items-center gap-2">
                                  {/* Diamond icon with color matching text */}
                                  <Icons.Diamond className="w-5 h-5 fill-current group-hover:scale-110 transition-transform" />
                                  <span className="font-bold tracking-wide">Diamonds</span> 
                              </div>
                          </button>
                      </div>

                      {/* Row 2: Bonus & Stats */}
